import type { ModuleKey } from '../types/models';
import { emptyFilters, type JournalFilters } from '../services/filters';
import { Button, Field, Input, Select } from './ui';

export function JournalFiltersPanel({ module, value, onChange, onDone }: { module: ModuleKey; value: JournalFilters; onChange: (value: JournalFilters) => void; onDone: () => void }) {
  const set = <K extends keyof JournalFilters>(key: K, next: JournalFilters[K]) => onChange({ ...value, [key]: next });
  return <div className="advanced-filters"><Field label="Сортировка"><Select value={value.sort} onChange={e => set('sort', e.target.value as JournalFilters['sort'])}><option value="new">Сначала новые</option><option value="old">Сначала старые</option><option value="number">По номеру</option><option value="due">По плановому сроку</option><option value="object">По объекту</option></Select></Field>{module !== 'photoReports' && <><Field label="Объект"><Input value={value.object} placeholder="№ ГП или название" onChange={e => set('object', e.target.value)} /></Field><Field label="Подрядчик"><Input value={value.contractor} onChange={e => set('contractor', e.target.value)} /></Field><Field label="Раздел работ"><Input value={value.discipline} onChange={e => set('discipline', e.target.value)} /></Field></>}{module === 'defects' && <><Field label="Критичность"><Select value={value.severity} onChange={e => set('severity', e.target.value)}><option value="">Любая</option><option>Обычное</option><option>Существенное</option><option>Критическое</option></Select></Field><label className="check-row"><input type="checkbox" checked={value.overdue} onChange={e => set('overdue', e.target.checked)} />Только просроченные</label></>}{module === 'inspections' && <Field label="Вид проверки"><Select value={value.kind} onChange={e => set('kind', e.target.value)}><option value="">Все виды</option><option>Операционный контроль</option><option>Приёмочный контроль</option><option>Индивидуальные испытания</option><option>Комплексное опробование</option></Select></Field>}<div className="form-grid"><Field label="Период с"><Input type="date" value={value.from} onChange={e => set('from', e.target.value)} /></Field><Field label="Период по"><Input type="date" value={value.to} onChange={e => set('to', e.target.value)} /></Field></div><Field label="Фотографии"><Select value={value.photos} onChange={e => set('photos', e.target.value as JournalFilters['photos'])}><option value="any">Не важно</option><option value="with">С фотографиями</option><option value="without">Без фотографий</option></Select></Field><div className="filter-footer"><Button variant="ghost" onClick={() => onChange(emptyFilters())}>Сбросить</Button><Button variant="primary" onClick={onDone}>Применить</Button></div></div>;
}
